export function getRoleBySlug(slug: string): RoleSystemKit | undefined {
  return ALL_ROLES.find((r) => r.slug === slug);
}

export function getAllRoleSlugs(): string[] {
  return ALL_ROLES.map((r) => r.slug);
}
